onClick:
{{
  (async () => {
    try {
      let idCible = select_article.selectedOptionValue;
      const qte = inp_quantite.text !== "" && !isNaN(inp_quantite.text) ? Number(inp_quantite.text) : 1;

      // Si rien n'est choisi dans le menu déroulant, on tente de lire l'input de scan
      if (!idCible && inp_scan_article.text?.trim()) {
        const code = inp_scan_article.text.trim().toLowerCase();
        const art = (Get_Tous_Articles.data || []).find(a => 
          (a.Code_Barre && a.Code_Barre.toLowerCase() === code) ||
          (a.Ref_Fournisseur && a.Ref_Fournisseur.toLowerCase() === code)
        );
        if (art) idCible = art.ID_Article;
      }

      if (!idCible) {
        showAlert('Veuillez sélectionner ou scanner un article', 'warning');
        storeValue('forceFocus', Date.now()); // <--- FORCER L'AUTOFOCUS
        return;
      }

      // Enregistrement manuel
      await Valider_Scan_Inv.run({ idArticle: idCible, quantite: qte });
      showAlert('✅ Scan enregistré !', 'success');

      // Nettoyage et rafraîchissement
      await Get_Derniers_Scans.run();
      await Get_Non_Scannes.run();
      resetWidget('select_article', true);
      resetWidget('inp_scan_article', true);
      resetWidget('inp_quantite', true);

      // <--- FORCER L'AUTOFOCUS MÊME APRÈS UN CLIC MANUEL
      storeValue('forceFocus', Date.now());

    } catch (err) {
      showAlert('Erreur lors de la validation : ' + err.message, 'error');
    }
  })()
}}
